class TextFieldExample extends StatefulWidget {
@override
_TextFieldExampleState createState() => _TextFieldExampleState();
}

class _TextFieldExampleState extends State<TextFieldExample> {
final TextEditingController _controller = TextEditingController();

@override
void initState() {
super.initState();
// Начальное значение
_controller.text = 'Привет';
// Слушатель изменений
_controller.addListener(() {
print('Текст: ${_controller.text}');
});
}

@override
void dispose() {
_controller.dispose(); // Обязательно!
super.dispose();
}

@override
Widget build(BuildContext context) {
return TextField(
controller: _controller,
decoration: const InputDecoration(
labelText: 'Текст',
border: OutlineInputBorder(),
),
);
}
}

// Очистка поля
_controller.clear();

// Установка текста
_controller.text = 'Новый текст';

// Вставка текста в позицию курсора
_controller.insertText('Вставленный текст');

// Получение выделенного текста
TextSelection selection = _controller.selection;
String selectedText = _controller.text.substring(
selection.start,
selection.end,
);

// Установка позиции курсора
_controller.selection = TextSelection.fromPosition(
TextPosition(offset: _controller.text.length),
);

TextField(
decoration: InputDecoration(
labelText: 'Email',
hintText: 'user@example.com',
prefixIcon: const Icon(Icons.email),
suffixIcon: IconButton(
icon: const Icon(Icons.clear),
onPressed: () {
_controller.clear();
},
),
helperText: 'Введите ваш email',
errorText: _hasError ? 'Неверный формат email' : null,
counterText: '${_controller.text.length} символов',
border: const OutlineInputBorder(),
focusedBorder: const OutlineInputBorder(
borderSide: BorderSide(color: Colors.blue, width: 2),
),
enabledBorder: const OutlineInputBorder(
borderSide: BorderSide(color: Colors.grey),
),
errorBorder: const OutlineInputBorder(
borderSide: BorderSide(color: Colors.red),
),
focusedErrorBorder: const OutlineInputBorder(
borderSide: BorderSide(color: Colors.red, width: 2),
),
filled: true,
fillColor: Colors.grey[100],
),
)

// Пунктирная граница
TextField(
decoration: InputDecoration(
border: OutlineInputBorder(
borderRadius: BorderRadius.circular(8),
borderSide: const BorderSide(
style: BorderStyle.solid,
width: 2,
),
),
),
)

// Без границы
TextField(
decoration: const InputDecoration(
border: InputBorder.none,
),
)

// Линия снизу
TextField(
decoration: const InputDecoration(
border: UnderlineInputBorder(),
),
)

// Email
TextField(
keyboardType: TextInputType.emailAddress,
decoration: const InputDecoration(labelText: 'Email'),
)

// Число
TextField(
keyboardType: TextInputType.number,
decoration: const InputDecoration(labelText: 'Возраст'),
)

// Телефон
TextField(
keyboardType: TextInputType.phone,
decoration: const InputDecoration(labelText: 'Телефон'),
)

// Пароль
TextField(
keyboardType: TextInputType.visiblePassword,
obscureText: true,
decoration: const InputDecoration(labelText: 'Пароль'),
)

// Многострочный
TextField(
maxLines: null, // null = неограниченное количество строк
keyboardType: TextInputType.multiline,
decoration: const InputDecoration(labelText: 'Комментарий'),
)

// Только цифры
TextField(
inputFormatters: [FilteringTextInputFormatter.digitsOnly],
decoration: const InputDecoration(labelText: 'Номер'),
)

// Только буквы
TextField(
inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[a-zA-Zа-яА-Я ]'))],
decoration: const InputDecoration(labelText: 'Имя'),
)

// Только разрешённые символы
TextField(
inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[0-9.]'))],
decoration: const InputDecoration(labelText: 'Цена'),
)

// Запрет символов
TextField(
inputFormatters: [FilteringTextInputFormatter.deny(RegExp(r'[<>]'))],
decoration: const InputDecoration(labelText: 'Без спецсимволов'),
)

// Ограничение длины
TextField(
inputFormatters: [LengthLimitingTextInputFormatter(50)],
decoration: const InputDecoration(
labelText: 'Комментарий',
counterText: '', // Скрыть стандартный счётчик
),
)

// Форматирование телефона: +7 (999) 123-45-67
class PhoneInputFormatter extends TextInputFormatter {
@override
TextEditingValue formatEditUpdate(
TextEditingValue oldValue,
TextEditingValue newValue,
) {
// Простая реализация
return newValue;
}
}

TextField(
inputFormatters: [PhoneInputFormatter()],
decoration: const InputDecoration(labelText: 'Телефон'),
)

class LoginScreen extends StatefulWidget {
@override
_LoginScreenState createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
final _formKey = GlobalKey<FormState>();
final _emailController = TextEditingController();
final _passwordController = TextEditingController();

bool _validateEmail(String value) {
return value.contains('@') && value.contains('.');
}

@override
Widget build(BuildContext context) {
return Form(
key: _formKey,
child: Column(
children: [
TextFormField(
controller: _emailController,
keyboardType: TextInputType.emailAddress,
decoration: const InputDecoration(
labelText: 'Email',
prefixIcon: Icon(Icons.email),
border: OutlineInputBorder(),
),
validator: (value) {
if (value == null || value.isEmpty) {
return 'Введите email';
}
if (!_validateEmail(value)) {
return 'Неверный формат';
}
return null;
},
),
const SizedBox(height: 16),
TextFormField(
controller: _passwordController,
obscureText: true,
decoration: const InputDecoration(
labelText: 'Пароль',
prefixIcon: Icon(Icons.lock),
border: OutlineInputBorder(),
),
validator: (value) {
if (value == null || value.isEmpty) {
return 'Введите пароль';
}
if (value.length < 6) {
return 'Минимум 6 символов';
}
return null;
},
),
const SizedBox(height: 24),
ElevatedButton(
onPressed: () {
if (_formKey.currentState!.validate()) {
// Форма валидна
print('Email: ${_emailController.text}');
print('Пароль: ${_passwordController.text}');
}
},
child: const Text('Войти'),
),
],
),
);
}

@override
void dispose() {
_emailController.dispose();
_passwordController.dispose();
super.dispose();
}
}
